float e(float l){return l*l*l*(l*(l*6.-15.)+10.);}float h(vec3 m){vec3 n=c*floor(m)+d;vec3 o=fract(m);float p=texture(permTexture,n.xy).a;vec3 q=texture(permTexture,vec2(p,n.z)).rgb*4.-1.;float s=dot(q,o);vec3 t=texture(permTexture,vec2(p,n.z+c)).rgb*4.-1.;float u=dot(t,o-vec3(.0,.0,1.));float w=texture(permTexture,n.xy+vec2(.0,c)).a;vec3 A=texture(permTexture,vec2(w,n.z)).rgb*4.-1.;float B=dot(A,o-vec3(.0,1.,.0));vec3 C=texture(permTexture,vec2(w,n.z+c)).rgb*4.-1.;float D=dot(C,o-vec3(.0,1.,1.));float E=texture(permTexture,n.xy+vec2(c,.0)).a;vec3 F=texture(permTexture,vec2(E,n.z)).rgb*4.-1.;float G=dot(F,o-vec3(1.,.0,.0));vec3 H=texture(permTexture,vec2(E,n.z+c)).rgb*4.-1.;float I=dot(H,o-vec3(1.,.0,1.));float J=texture(permTexture,n.xy+vec2(c,c)).a;vec3 K=texture(permTexture,vec2(J,n.z)).rgb*4.-1.;float L=dot(K,o-vec3(1.,1.,.0));vec3 M=texture(permTexture,vec2(J,n.z+c)).rgb*4.-1.;float N=dot(M,o-vec3(1.,1.,1.));vec4 O=mix(vec4(s,u,B,D),vec4(G,I,L,N),e(o.x));vec2 Q=mix(O.xy,O.zw,e(o.y));float R=mix(Q.x,Q.y,e(o.z));return R;}float i(float T,float U,float V,float W,float X){return(T-U)*(X-W)/(V-U)+W;}void j(){float Y=i(dc,0,1.4,0,12.6);float Z=Y+elapsed;float ab=i(sin(Z),-1.,1.,.4,1.);float cb=i(sin(Z+2),-1.,1.,.4,1.);float eb=i(sin(Z+4),-1.,1.,.4,1.);fragColor=vec4(ab,cb,eb,1.)*lightIntensity*lightIntensity;}void k(){vec2 gb=vsoTexCoord*400.;float ib=gb.x*6.28/400.;float kb=.8;float mb=.4*kb;float ob=h(vec3(cos(ib)*mb,kb*gb.y*.01+-elapsed*.2*24.,sin(ib)*mb))*.5+.5;float qb=h(vec3(cos(ib)*mb,kb*gb.y*.001+-elapsed*.02*24.,sin(ib)*mb))*.5+.5;float sb=h(vec3(cos(ib)*mb*.1+2.,kb*gb.y*.001+-elapsed*.06*24.,sin(ib)*mb*.1))*.5+.5;fragColor=vec4(ob,ob,ob,1.);fragColor=vec4(1.-(ob*ob*qb+sb)*1.,1.-(ob*ob*qb+sb)*.75,1.-(ob*ob*qb+sb)*.5,1.);}void main(){if(drawSky==1){k();}else{j();}}